-- Generated from src/lib/server/db.ts (in-memory mock data) to seed real business
-- data into the pipeline schema. Run after db:seed (schema + reference data).
-- Idempotent: every statement is a no-op on a second run.

ON CONFLICT (customer) DO NOTHING;

ON CONFLICT (workload) DO NOTHING;

-- Hand-authored check-in events: plain customer/workload check-ins, no size/stage change.
ON CONFLICT (event) DO NOTHING;

-- Backfilled history establishing each workload's current size/stage, mirroring
-- `backfill_workload_history` in db.ts: a rich multi-entry progression for a few
-- workloads, a single 'Initial creation' entry for the rest.
ON CONFLICT (event) DO NOTHING;
